-- Permisos de tabla para el rol "authenticated" (usuarios con sesión).
-- Sin estos GRANT, PostgreSQL responde "permission denied for table ..."
-- antes incluso de evaluar las políticas RLS. RLS sigue limitando qué filas ve cada usuario.
GRANT USAGE ON SCHEMA public TO authenticated;

GRANT SELECT, INSERT, UPDATE, DELETE ON
  perfiles, alimentos, registro_diario, menus, detalle_menu
TO authenticated;

-- Necesario para las columnas id GENERATED BY DEFAULT AS IDENTITY.
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO authenticated;

-- El rol anónimo (sin sesión) no necesita acceso a ninguna tabla.
REVOKE ALL ON perfiles, alimentos, registro_diario, menus, detalle_menu FROM anon;
